const e="../schema/spec.schema.json",a="ps",s="Report a snapshot of the current processes",t=[{name:"-e",description:"Select all processes"},{name:"-A",description:"Select all processes"},{name:"-f",description:"Full-format listing"},{name:"-l",description:"Long format"},{name:"-a",description:"Select all processes except session leaders and those without a terminal"},{name:"-u",description:"Select by effective user",args:[{name:"user"}]},{name:"-p",description:"Select by process ID",args:[{name:"pid[,pid...]"}]},{name:"-C",description:"Select by command name",args:[{name:"name"}]},{name:"-t",description:"Select by terminal",args:[{name:"tty"}]},{name:"-o",description:"User-defined output format",args:[{name:"format",suggestions:["pid,ppid,user,%cpu,%mem,etime,cmd","pid,comm","pid,%mem,rss,cmd"]}]},{name:"-T",description:"Show threads"},{name:"-H",description:"Show the process hierarchy"},{name:"-w",description:"Wide output"},{name:"--forest",description:"ASCII art process tree"},{name:"--sort",description:"Sort by these keys, such as -%cpu",args:[{name:"key",suggestions:["-%cpu","-%mem","pid","start_time"]}]},{name:"--no-headers",description:"Print no header line"}],n=[{name:"style",optional:!0,suggestions:[{name:"aux",description:"All processes, user-oriented format"},{name:"auxf",description:"All processes as a tree"}]}],o={$schema:e,name:"ps",description:s,options:t,args:n};export{e as $schema,n as args,o as default,s as description,a as name,t as options};
